import json
from itertools import product

with open('/app/puzzles.json') as f:
    puzzles = json.load(f)

OPS = ['⊕', '⊗', '◇', '▽', '⊘', '⊛', '⊞', '⊠', '△']

def ev(op, a, b):
    if op == '⊞': return a + b
    if op == '⊕': return a + b + 1
    if op == '⊠': return a + b + 2
    if op == '⊗': return a * b - 1
    if op == '◇': return max(a, b)
    if op == '▽': return abs(a - b)
    if op == '△': return max(0, a - b)
    if op == '⊘': return 2 * a - b
    if op == '⊛': return a + b ** 2

def eval_tree(tree_id, nums, ops):
    x0, x1, x2, x3 = nums
    o1, o2, o3 = ops
    if tree_id == 0:
        return ev(o3, ev(o2, ev(o1, x0, x1), x2), x3), f"{x0} {o1} {x1} {o2} {x2} {o3} {x3}"
    elif tree_id == 1:
        return ev(o3, ev(o1, x0, ev(o2, x1, x2)), x3), f"{x0} {o1} ({x1} {o2} {x2}) {o3} {x3}"
    elif tree_id == 2:
        return ev(o2, ev(o1, x0, x1), ev(o3, x2, x3)), f"({x0} {o1} {x1}) {o2} ({x2} {o3} {x3})"
    elif tree_id == 3:
        return ev(o1, x0, ev(o3, ev(o2, x1, x2), x3)), f"{x0} {o1} ({x1} {o2} {x2} {o3} {x3})"
    elif tree_id == 4:
        return ev(o1, x0, ev(o2, x1, ev(o3, x2, x3))), f"{x0} {o1} ({x1} {o2} ({x2} {o3} {x3}))"

# Check all values for P3 near 218
p3_vals = set()
for tid in range(5):
    for ops in product(OPS, repeat=3):
        v, s = eval_tree(tid, puzzles['P3']['numbers'], ops)
        p3_vals.add(v)
near_218 = sorted([v for v in p3_vals if abs(v - 218) <= 5])
print("P3 values near 218:", near_218)

# Verify each solution by parsing and evaluating independently
def parse_and_eval(expr):
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
        elif expr[i] in '()':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(expr[i])
            i += 1
    pos = [0]
    def parse_expr():
        val = parse_atom()
        while pos[0] < len(tokens) and tokens[pos[0]] in OPS:
            op = tokens[pos[0]]
            pos[0] += 1
            rhs = parse_atom()
            val = ev(op, val, rhs)
        return val
    def parse_atom():
        if tokens[pos[0]] == '(':
            pos[0] += 1
            val = parse_expr()
            assert tokens[pos[0]] == ')'
            pos[0] += 1
            return val
        else:
            val = tokens[pos[0]]
            pos[0] += 1
            return val
    res = parse_expr()
    assert pos[0] == len(tokens)
    return res

ans = {
    "P1": "(7 ⊛ 3) ⊛ (5 ⊠ 8)",
    "P2": "(5 ⊛ 8) ⊘ (3 ▽ 5)",
    "P3": "none",
    "P4": "6 ⊛ 8 ⊠ 6 ⊘ 9",
    "P5": "5 ⊗ (7 △ 9 ⊛ 7)",
    "P6": "8 ⊗ (3 ⊕ 5) ⊛ 7",
    "P7": "8 ▽ (6 ⊗ (8 ⊠ 8))",
    "P8": "9 ◇ (8 ⊛ (7 ⊕ 8))"
}

for pk in sorted(ans.keys()):
    if ans[pk] == "none":
        print(f"{pk}: none (target={puzzles[pk]['target']})")
    else:
        val = parse_and_eval(ans[pk])
        print(f"{pk}: {ans[pk]} = {val} (target={puzzles[pk]['target']}, match={val == puzzles[pk]['target']})")
